import'package:flutter/material.dart';import'../../core/network/api_client.dart';
class NotificationsScreen extends StatefulWidget{const NotificationsScreen({super.key,required this.api});final ApiClient api;@override State<NotificationsScreen>createState()=>_State();}class _State extends State<NotificationsScreen>{List<dynamic>items=[];String?error;@override void initState(){super.initState();load();}Future<void>load()async{try{final r=await widget.api.dio.get<List<dynamic>>('/api/v1/notifications');if(mounted)setState((){items=r.data??[];error=null;});}catch(_){if(mounted)setState(()=>error='Pa kapab chaje notifications yo.');}}Future<void>read(Map<String,dynamic>item)async{if(item['readAt']!=null)return;await widget.api.dio.patch('/api/v1/notifications/${item['id']}/read');await load();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Notifications')),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(12),children:[if(error!=null)Text(error!),if(items.isEmpty&&error==null)const ListTile(title:Text('Pa gen notification.')),for(final raw in items)Builder(builder:(_){final n=raw as Map<String,dynamic>;return Card(child:ListTile(onTap:()=>read(n),leading:Icon(n['readAt']==null?Icons.notifications_active:Icons.notifications_none),title:Text('${n['title']}'),subtitle:Text('${n['body']}'),trailing:n['readAt']==null?const Badge():null));})])));}
